<template>
  <page-meta v-if="isWeapp" :page-style="pageMeta.pageStyle" :background-color="pageMeta.backgroundColor" :background-color-top="pageMeta.backgroundColorTop" :background-color-bottom="pageMeta.backgroundColorBottom" :background-text-style="pageMeta.backgroundTextStyle" />
  <view class="se-page" :class="themeClass">
    <view v-if="loading" class="se-state">正在加载…</view>
    <view v-else-if="!item" class="se-state"><text class="se-state-title">练习暂不可用</text><text class="se-state-desc">请返回练习列表后重试。</text></view>
    <template v-else>
      <view class="se-heading"><text class="se-kind">{{ typeName(item.question_type) }}</text><text v-if="item.difficulty" class="se-difficulty">{{ item.difficulty }}</text><text class="se-heading-title">{{ item.title }}</text><text class="se-source">{{ item.source_title }}<text v-if="item.source_date"> · {{ item.source_date }}</text></text></view>
      <view class="se-section"><text class="se-section-title">材料</text><text class="se-material">{{ item.source_excerpt }}</text><text v-if="item.source_url" class="se-source-link" @tap="openSource">查看来源文章 ↗</text></view>
      <view class="se-section se-prompt"><text class="se-section-title">作答任务</text><text class="se-prompt-text">{{ item.prompt }}</text><text v-if="item.requirements" class="se-requirement">{{ item.requirements }}</text><text v-if="item.max_chars" class="se-limit">建议 {{ item.max_chars }} 字以内</text></view>
      <view v-if="item.hint && !submitted" class="se-hint" @tap="toggleHint"><text class="se-hint-label">审题提示 {{ showHint?'收起':'展开' }}</text><text v-if="showHint" class="se-hint-text">{{ item.hint }}</text></view>
      <view class="se-section se-answer"><view class="se-answer-head"><text class="se-section-title">{{ submitted?'我的作答':'写下你的答案' }}</text><text class="se-count">{{ answer.length }}{{ item.max_chars?` / ${item.max_chars}`:'' }}</text></view><textarea class="se-textarea" :value="answer" :maxlength="12000" :placeholder="submitted?'首次作答已保存':'先独立完成，再提交查看参考要点'" :disabled="submitted" @input="onAnswerInput" /></view>
      <view v-if="!submitted" class="se-actions"><button class="se-primary" :disabled="!answer.trim()||saving" @tap="submit">{{ saving?'提交中…':'提交并查看解析' }}</button></view>
      <template v-if="submitted">
        <view class="se-feedback-head"><text class="se-feedback-title">参考答案与自查</text><text class="se-feedback-tip">逐项核对材料依据，不以措辞完全一致为标准。</text></view>
        <view v-if="item.key_points.length" class="se-section"><text class="se-section-title">关键要点与材料依据</text><view v-for="(point,index) in item.key_points" :key="`${index}-${point.point}`" class="se-point"><text class="se-point-num">{{ String(index+1).padStart(2,'0') }}</text><view class="se-point-body"><text class="se-point-title">{{ point.point }}</text><text class="se-point-evidence">材料依据：{{ point.evidence }}</text></view></view></view>
        <view v-if="item.rubric.length" class="se-section"><text class="se-section-title">自查清单</text><view v-for="row in item.rubric" :key="row.name" class="se-rubric"><text class="se-rubric-name">{{ row.name }}</text><text class="se-rubric-desc">{{ row.description }}</text></view></view>
        <view v-if="item.sample_answer" class="se-section"><text class="se-section-title">参考答案</text><text class="se-material">{{ item.sample_answer }}</text></view>
        <view v-if="item.analysis" class="se-section"><text class="se-section-title">解析</text><text class="se-material">{{ item.analysis }}</text></view>
        <view class="se-section se-revise"><text class="se-section-title">订正一遍</text><text class="se-revise-tip">先对照要点修改答案，再写一句本次发现。</text><textarea class="se-textarea" :value="revision" :maxlength="12000" placeholder="写下修订后的答案" @input="onRevisionInput" /><textarea class="se-reflection" :value="reflection" :maxlength="2000" placeholder="我这次漏掉 / 改进的是…" @input="onReflectionInput" /><button class="se-secondary" :disabled="!revision.trim()||saving" @tap="saveRevision">{{ saving?'保存中…':item.attempt?.revision?'更新订正':'保存订正' }}</button><text v-if="item.attempt?.revision" class="se-saved">订正已保存，可继续修改。</text></view>
        <view v-if="item.related_assets.length" class="se-section"><text class="se-section-title">相关积累</text><text v-for="asset in item.related_assets" :key="`${asset.type}-${asset.id}`" class="se-asset">{{ asset.title }}</text></view>
      </template>
      <view class="se-footer">内容基于已审核材料 · 作答建议结合题目要求与原文依据</view>
    </template>
  </view>
</template>
<script setup lang="ts">
import { onMounted,ref } from 'vue'
import Taro,{useRouter} from '@tarojs/taro'
import {api} from '@/api'
import type {ShenlunExerciseCard} from '@/api/domains/rmrb'
import {useThemeClass,usePageMeta} from '@/utils/brandColor'
import {showToast} from '@/utils/platform'
definePageConfig({navigationBarTitleText:'申论练习'})
const router=useRouter(),{themeClass}=useThemeClass(),pageMeta=usePageMeta(),isWeapp=process.env.TARO_ENV==='weapp'
const item=ref<ShenlunExerciseCard|null>(null),loading=ref(true),saving=ref(false),answer=ref(''),revision=ref(''),reflection=ref(''),submitted=ref(false),showHint=ref(false)
const id=String(router.params?.id||''),storageKey=`shenlun-exercise-draft:${id}`
const submittedValue=()=>Boolean(item.value?.attempt)
function typeName(v:string){return ({summary:'归纳概括',countermeasure:'提出对策',implementation:'贯彻执行',essay:'申发论述'} as Record<string,string>)[v]||'申论练习'}
async function load(){loading.value=true;try{const res=await api.getShenlunExercise(id);if(res.code!==0||!res.data){showToast(res.message||'练习加载失败','error');return}item.value=res.data;submitted.value=submittedValue();if(submitted.value){answer.value=res.data.attempt?.answer||'';revision.value=res.data.attempt?.revision||'';reflection.value=res.data.attempt?.reflection||''}else{answer.value=Taro.getStorageSync(storageKey)||''}}catch{showToast('练习加载失败','error')}finally{loading.value=false}}
function onAnswerInput(e:{detail:{value:string}}){answer.value=e.detail.value;Taro.setStorageSync(storageKey,answer.value)}
function onRevisionInput(e:{detail:{value:string}}){revision.value=e.detail.value}
function onReflectionInput(e:{detail:{value:string}}){reflection.value=e.detail.value}
function toggleHint(){showHint.value=!showHint.value}
function openSource(){if(item.value?.source_url)Taro.setClipboardData({data:item.value.source_url}).then(()=>showToast('来源链接已复制','success'))}
async function submit(){if(!answer.value.trim()){showToast('先写下你的作答');return}saving.value=true;try{const res=await api.submitShenlunExercise(id,answer.value.trim());if(res.code===0&&res.data){item.value=res.data;submitted.value=true;Taro.removeStorageSync(storageKey);showToast('已提交，参考解析已解锁','success')}else showToast(res.message||'提交失败','error')}catch{showToast('提交失败，请稍后重试','error')}finally{saving.value=false}}
async function saveRevision(){if(!item.value?.attempt?.id||!revision.value.trim())return;saving.value=true;try{const res=await api.reviseShenlunExercise(id,item.value.attempt.id,revision.value.trim(),reflection.value.trim());if(res.code===0&&res.data){item.value=res.data;showToast('订正已保存','success')}else showToast(res.message||'保存失败','error')}catch{showToast('保存失败','error')}finally{saving.value=false}}
onMounted(load)
</script>
<style lang="scss" scoped>
@import '@/styles/variables.scss';
.se-page{@include page-padding;padding-bottom:36px}.se-heading{@include card;margin-bottom:12px}.se-kind{@include brand-chip;display:inline-block}.se-difficulty{margin-left:8px;@include muted-chip}.se-heading-title{display:block;margin-top:12px;font-size:20px;line-height:1.4;font-weight:700;color:$text-primary}.se-source{display:block;margin-top:8px;font-size:12px;color:$text-muted}.se-section{@include card;margin-bottom:10px}.se-section-title{display:block;margin-bottom:10px;font-size:15px;font-weight:700;color:$text-primary}.se-material,.se-prompt-text{display:block;white-space:pre-wrap;font-size:14px;line-height:1.75;color:$text-primary}.se-source-link{display:inline-block;margin-top:10px;font-size:12px;color:$primary-color}.se-requirement{display:block;margin-top:10px;font-size:13px;line-height:1.6;color:$text-secondary}.se-limit{display:inline-block;margin-top:10px;padding:4px 8px;border-radius:8px;background:$elevated;color:$text-muted;font-size:12px}.se-hint{padding:12px 14px;margin-bottom:10px;border:1px solid $border-color;border-radius:$radius-md;background:$elevated}.se-hint-label{display:block;color:$primary-color;font-size:13px;font-weight:600}.se-hint-text{display:block;margin-top:8px;color:$text-secondary;font-size:13px;line-height:1.6}.se-answer-head{display:flex;justify-content:space-between;align-items:center}.se-count{font-size:12px;color:$text-muted}.se-textarea,.se-reflection{display:block;width:100%;min-height:170px;padding:12px;border:1px solid $border-color;border-radius:$radius-md;background:$input-bg;color:$text-primary;font-size:14px;line-height:1.65;box-sizing:border-box}.se-textarea:disabled{opacity:.85}.se-reflection{min-height:72px;margin-top:10px}.se-actions{position:sticky;bottom:12px;padding:4px 0 12px}.se-primary,.se-secondary{width:100%;min-height:46px;border:0;border-radius:$radius-md;background:$primary-color;color:#fff;font-size:15px;font-weight:600}.se-primary[disabled],.se-secondary[disabled]{opacity:.55}.se-feedback-head{padding:16px 4px 8px}.se-feedback-title{display:block;font-size:18px;font-weight:700;color:$text-primary}.se-feedback-tip,.se-revise-tip{display:block;margin-top:5px;font-size:12px;line-height:1.55;color:$text-muted}.se-point{display:flex;gap:10px;padding:12px 0;border-top:1px solid $border-color}.se-point-num{color:$primary-color;font-size:12px;font-weight:700}.se-point-body{flex:1}.se-point-title{display:block;font-size:14px;line-height:1.5;font-weight:600;color:$text-primary}.se-point-evidence{display:block;margin-top:6px;font-size:12px;line-height:1.55;color:$text-secondary}.se-rubric{padding:9px 0;border-top:1px solid $border-color}.se-rubric-name{display:block;font-size:13px;font-weight:600;color:$text-primary}.se-rubric-desc{display:block;margin-top:3px;font-size:12px;line-height:1.5;color:$text-secondary}.se-secondary{margin-top:10px;background:$elevated;color:$primary-color;border:1px solid $border-color}.se-saved{display:block;margin-top:8px;color:$success;font-size:12px}.se-asset{display:block;padding:8px 0;border-top:1px solid $border-color;font-size:13px;color:$text-secondary}.se-footer{padding:10px 2px;color:$text-muted;font-size:11px;line-height:1.5}.se-state{@include page-state-box;margin-top:28px}.se-state-title{display:block;font-size:15px;font-weight:600;color:$text-primary}.se-state-desc{display:block;margin-top:5px;font-size:13px;color:$text-muted}
</style>
